 const ethPrice=Number(markets.find(m=>m.symbol==="ETH")?.price||0),portfolioRows=walletAddress?[{asset:"ETH",quantity:Number(walletNativeBalance||0),price:ethPrice,value:Number(walletNativeBalance||0)*ethPrice},{asset:"WETH",quantity:Number(walletWethBalance||0),price:ethPrice,value:Number(walletWethBalance||0)*ethPrice},{asset:"USDC",quantity:Number(walletUsdcBalance||0),price:1,value:Number(walletUsdcBalance||0)}].filter(x=>x.quantity>0):[],portfolioTotal=portfolioRows.reduce((sum,x)=>sum+x.value,0);

 const filteredIndexedHistory=indexedHistory.filter(item=>{const incoming=String(item.to||"").toLowerCase()===walletAddress.toLowerCase();const outgoing=String(item.from||"").toLowerCase()===walletAddress.toLowerCase();return chainDirection==="all"||(chainDirection==="incoming"&&incoming)||(chainDirection==="outgoing"&&outgoing);});
 function indexedAssetAmount(item){if(item.kind!=="token_transfer")return item.value||"—";const decimals=Number(item.decimals);const raw=String(item.value??"");if(!/^\\d+$/.test(raw)||!Number.isInteger(decimals)||decimals<0||decimals>36)return raw||"—";const base=10n**BigInt(decimals),amount=BigInt(raw),whole=amount/base;let fraction=(amount%base).toString().padStart(decimals,"0").slice(0,8).replace(/0+$/,"");return whole.toLocaleString("en-US")+(fraction?"."+fraction:"");}
 const filteredWalletActivity=walletActivity.filter(a=>{const q=activitySearch.trim().toLowerCase();const matchesSearch=!q||[a.hash,a.asset,a.kind,a.address,CHAINS[a.chainId]?.name||a.chainId].some(v=>String(v||"").toLowerCase().includes(q));return matchesSearch&&(activityStatus==="all"||(a.status||"unknown")===activityStatus)&&(activityKind==="all"||a.kind===activityKind);});
