 function exportPaperOrders(){if(!filteredOrders.length)return;const cols=["id","created_at","symbol","side","quantity","price","notional","fee","status"];const quote=v=>'"'+String(v??"").replace(/"/g,'""')+'"';const csv=[cols.join(","),...filteredOrders.map(o=>cols.map(k=>quote(o[k])).join(","))].join("\r\n");const blob=new Blob(["\uFEFF",csv],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download="zencrypto-paper-orders.csv";document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);}
